/* Performance: histórico real e limitado; nenhum dado ou pico é simulado. */
(()=>{
 'use strict';
 livingIcons.performance='<path d="M4.9 19a9 9 0 1 1 14.2 0M8 18h8m-4-4 5-6"/><circle cx="12" cy="14" r="1.5"/>';
 const nav=document.createElement('button');nav.className='nav';nav.dataset.page='performance';nav.innerHTML=livingIcon('performance')+'<span class="nav-label">Performance</span>';nav.setAttribute('aria-label','Performance da TV');$('#themes').before(nav);describeControl(nav,'Performance da TV','RAM, CPU, rede e histórico');
 function gauge(id,label,color){return '<article class="perf-gauge" style="--metric-color:'+color+'"><div class="perf-card-title">'+label+'<small id="perf-'+id+'-hint">Aguardando leitura</small></div><div class="perf-dial"><svg viewBox="0 0 200 150" aria-hidden="true"><defs><linearGradient id="perf-gradient-'+id+'" x1="0" y1="1" x2="1" y2="0"><stop stop-color="#8447ef"/><stop offset=".5" stop-color="'+color+'"/><stop offset="1" stop-color="#9debdc"/></linearGradient></defs><path class="perf-track" d="M30 125A80 80 0 1 1 170 125" pathLength="100"/><path id="perf-'+id+'-arc" class="perf-progress" d="M30 125A80 80 0 1 1 170 125" pathLength="100" stroke="url(#perf-gradient-'+id+')" stroke-dasharray="0 100"/><path class="perf-ticks" d="M30 125A80 80 0 1 1 170 125" pathLength="100"/><circle id="perf-'+id+'-needle-dot" class="perf-needle-dot" cx="100" cy="104" r="4"/></svg><strong id="perf-'+id+'-value">—</strong><span id="perf-'+id+'-sub">Sem amostra</span></div><div class="perf-mini-graph">'+livingChart('perf-'+id+'-line')+'</div><p id="perf-'+id+'-note">Dados reais da Konka</p></article>'}
 const section=document.createElement('section');section.id='performance-dashboard';section.className='performance-dashboard';section.hidden=true;section.setAttribute('aria-label','Performance da Konka');
 section.innerHTML='<div class="perf-header"><div><p class="eyebrow">SUA KONKA · POR DENTRO</p><h1>Performance em perspectiva.</h1><p>Leituras reais. Um gráfico para cada medida.</p></div><div><span id="perf-state">Aguardando conexão</span><small id="perf-updated">Sem leitura</small><button id="perf-refresh">Atualizar leitura</button></div></div><div class="perf-gauge-grid">'+gauge('ram','Memória RAM','#c77bff')+gauge('cpu','Processador','#4bd8db')+gauge('network','Tráfego de rede','#ffaf69')+'</div><div class="perf-detail-grid"><article class="perf-detail"><h3>Memória, sem confusão</h3><div class="perf-memory-segments"><i id="perf-used-bar"></i><i id="perf-free-bar"></i></div><dl><dt>Em uso / disponível</dt><dd id="perf-memory-detail">—</dd><dt>Cache de arquivos · Cached</dt><dd id="perf-cache">—</dd><dt>Swap / zRAM em uso</dt><dd id="perf-swap">—</dd><dt>Armazenamento livre</dt><dd id="perf-storage">—</dd></dl></article><article class="perf-detail"><h3>Conexões</h3><div class="perf-connection-row"><span>'+livingIcon('wifi')+'<b id="perf-wifi">Sem leitura Wi-Fi</b></span><span class="hub-bars" id="perf-bars"><i></i><i></i><i></i><i></i></span></div><div class="perf-connection-row"><span>'+livingIcon('bluetooth')+'<b id="perf-bluetooth">Leitura Bluetooth na TV</b></span><button id="perf-bt-open">Ver dispositivos</button></div><p id="perf-traffic-explanation">Tráfego medido na interface da TV, em Mb/s. A escala acompanha o pico observado nesta sessão e não representa a capacidade do seu plano.</p></article><article class="perf-detail"><h3>Sistema</h3><dl><dt>Modelo / Android</dt><dd id="perf-model">—</dd><dt>Tempo ligado</dt><dd id="perf-uptime">—</dd><dt>Carga · 1 / 5 / 15 min</dt><dd id="perf-load">—</dd><dt>Sensor térmico 0</dt><dd id="perf-temperature">Não informado</dd></dl><p>Sensor sem identificação do componente. Não é apresentado como temperatura da CPU.</p></article></div><div class="perf-process-card"><div><h3>Processos que usam memória</h3><p>Consulta manual de PSS: considera a parcela proporcional da memória compartilhada.</p></div><button id="perf-process-refresh">Consultar processos</button><div id="perf-process-list"></div></div><p class="perf-footnote">Amostras a cada 15 segundos com esta seção ativa. Até 60 pontos por gráfico. Nenhum aplicativo é encerrado. A RAM do sistema inteiro é diferente da memória usada pelo Peep Connect.</p>';
 $('main').append(section);
 let diagnostics=null,diagError='',busy=false,warmRetries=0,lastAt=null,lastDiagsAt=null;const history={ram:[],cpu:[],down:[],up:[],at:[],cpuAt:[]};
 const cap=(value,min,max)=>Math.max(min,Math.min(max,value));
 function push(name,value){if(Number.isFinite(value)){history[name].push(value);if(history[name].length>60)history[name].shift()}}
 // A coleta pertence ao evento de telemetria: o histórico já existe ao abrir a guia, sem nova consulta.
 function collect(d=liveTV){if(!d?.connected||!Number.isFinite(d.at)||d.at===lastAt||tvError)return;if(history.at.length&&d.at-history.at.at(-1)>30)for(const key of ['ram','down','up','at'])history[key].length=0;lastAt=d.at;const total=d.ram?.totalBytes,available=d.ram?.availableBytes;push('ram',total&&Number.isFinite(available)?100*(1-available/total):null);push('down',d.network?.traffic?.downloadMbps);push('up',d.network?.traffic?.uploadMbps);history.at.push(d.at);if(history.at.length>60)history.at.shift()}
 window.addEventListener('peep-metrics',event=>collect(event.detail));
 function span(name,unit,digits=0){const v=history[name].filter(Number.isFinite);if(v.length<2)return 'Histórico: aguardando 2 leituras';const t=name==='cpu'?history.cpuAt:history.at,secs=t.length>1?Math.round(t.at(-1)-t[0]):0;return 'Mín '+livingNum(Math.min(...v),digits)+unit+' · máx '+livingNum(Math.max(...v),digits)+unit+' · '+v.length+' leituras'+(secs?' em '+(secs>=120?Math.round(secs/60)+' min':secs+' s'):'')}
 function setRange(id,text){let el=$('#perf-'+id+'-range');if(!el){el=document.createElement('small');el.id='perf-'+id+'-range';el.className='perf-range';$('#perf-'+id+'-line')?.closest('.perf-mini-graph')?.after(el)}if(el&&el.textContent!==text)el.textContent=text}
 function band(values,floor=0,ceil=100,minSpan=10){const v=values.filter(Number.isFinite);if(!v.length)return [floor,ceil];let low=Math.min(...v),high=Math.max(...v);const pad=Math.max(minSpan-(high-low),0)/2+1;return [Math.max(floor,Math.floor(low-pad)),Math.min(ceil,Math.ceil(high+pad))]}
 function setDial(id,value,display,sub){const good=Number.isFinite(value);$('#perf-'+id+'-arc').setAttribute('stroke-dasharray',(good?cap(value,0,100):0)+' 100');richSetText('perf-'+id+'-value',display);richSetText('perf-'+id+'-sub',sub);$('#perf-'+id+'-needle-dot').style.opacity=good?'1':'.2'}
 function paint(){
  const d=liveTV,valid=!!d&&!tvError&&Date.now()/1000-d.at<45,total=d?.ram?.totalBytes,available=d?.ram?.availableBytes,ram=valid&&total&&Number.isFinite(available)?100*(1-available/total):null;
  const cpuFresh=diagnostics&&Date.now()/1000-diagnostics.at<45&&!diagError,cpu=cpuFresh?diagnostics.cpu?.usagePercent:null,down=valid?d?.network?.traffic?.downloadMbps:null,up=valid?d?.network?.traffic?.uploadMbps:null;
  if(valid)collect(d);if(cpuFresh&&diagnostics.at!==lastDiagsAt){lastDiagsAt=diagnostics.at;push('cpu',cpu);if(Number.isFinite(cpu)){history.cpuAt.push(diagnostics.at);if(history.cpuAt.length>60)history.cpuAt.shift()}}
  setDial('ram',ram,Number.isFinite(ram)?Math.round(ram)+'%':'—',total?gib(total)+' GiB no sistema':'Sem leitura');
  setDial('cpu',cpu,Number.isFinite(cpu)?Math.round(cpu)+'%':'—',diagnostics?.cpu?.warmingUp?'Coletando 2ª amostra':diagError?'Consulta indisponível':diagnostics?.cpu?.available===false?'Leitura restrita pelo Android':'Uso total entre amostras');
  const observedPeak=Math.max(0,...history.down,...history.up),peak=Math.max(.1,observedPeak);setDial('network',Number.isFinite(down)?down/peak*100:null,Number.isFinite(down)?livingNum(down,2):'—','↓ Download · Mb/s');
  richSetText('perf-ram-hint',valid?'Sistema inteiro':'Sem leitura atual');richSetText('perf-cpu-hint',cpuFresh?'Leitura do Android':'Aguardando CPU');richSetText('perf-network-hint','↑ '+livingNum(up,2)+' Mb/s');
  richSetText('perf-ram-note',valid?gib(available)+' GiB disponíveis':'Conecte a TV por ADB');richSetText('perf-cpu-note',cpuFresh?'Amostra das '+new Date(diagnostics.at*1000).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',second:'2-digit'})+' · ADB a cada 15 s':'Sem estimativas quando a leitura não está disponível');richSetText('perf-network-note','Pico observado: '+livingNum(observedPeak,2)+' Mb/s');
  const ramBand=band(history.ram),cpuBand=band(history.cpu,0,100,20);livingSetChart('perf-ram-line',history.ram,ramBand,'Uso da RAM em percentual, escala '+ramBand[0]+'–'+ramBand[1]+'%');livingSetChart('perf-cpu-line',history.cpu,cpuBand,'Uso da CPU em percentual, escala '+cpuBand[0]+'–'+cpuBand[1]+'%');setRange('ram',span('ram','%'));setRange('cpu',span('cpu','%'));livingSetChart('perf-network-line',history.down,[0,peak],'Download em Mb/s');
  let upload=$('#perf-upload-line');if(!upload){upload=document.createElementNS('http://www.w3.org/2000/svg','path');upload.id='perf-upload-line';upload.classList.add('perf-upload-line');$('#perf-network-line').closest('svg').append(upload)}upload.setAttribute('d',livingPath(history.up,0,peak));
  richSetText('perf-state',valid?'Konka conectada':'Sem leitura atual da Konka');richSetText('perf-updated',d?'Leitura '+new Date(d.at*1000).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Sem horário');
  richSetText('perf-memory-detail',valid?gib(total-available)+' / '+gib(available)+' GiB':'—');$('#perf-used-bar').style.width=(ram||0)+'%';$('#perf-free-bar').style.width=Number.isFinite(ram)?100-ram+'%':'0%';
  const mem=cpuFresh?diagnostics.memory:null;richSetText('perf-cache',Number.isFinite(mem?.Cached)?gib(mem.Cached)+' GiB · campo Cached':'Não informado');richSetText('perf-swap',mem&&Number.isFinite(mem.SwapTotal)&&Number.isFinite(mem.SwapFree)?gib(mem.SwapTotal-mem.SwapFree)+' / '+gib(mem.SwapTotal)+' GiB':'Não informado');
  richSetText('perf-storage',valid&&Number.isFinite(d.storage?.availableBytes)?gib(d.storage.availableBytes)+' GiB':'—');richSetText('perf-wifi',valid?(d.network.transport||'Rede')+(Number.isFinite(d.network.rssi)?' · '+d.network.rssi+' dBm':''):'Sem leitura de rede');
  const level=valid&&Number.isFinite(d.network.rssi)?d.network.rssi>=-55?4:d.network.rssi>=-67?3:d.network.rssi>=-75?2:1:0;$('#perf-bars').querySelectorAll('i').forEach((bar,i)=>bar.classList.toggle('on',i<level));
  const bt=horizonBluetooth,canBT=typeof PeepTV!=='undefined'&&typeof PeepTV.bluetoothStatus==='function';richSetText('perf-bluetooth',!canBT?'Bluetooth · leitura no app da TV':bt.state==='permission'?'Bluetooth · autorizar leitura':bt.state==='off'?'Bluetooth desativado':(bt.devices?.length||0)+' Bluetooth conectado'+(bt.devices?.length!==1?'s':''));
  richSetText('perf-model',valid?d.model+' · Android '+d.android:'—');richSetText('perf-uptime',valid?Math.floor(d.uptimeSeconds/3600)+' h '+Math.floor(d.uptimeSeconds%3600/60)+' min':'—');richSetText('perf-load',cpuFresh&&diagnostics.loadAverage?.length===3?diagnostics.loadAverage.map(x=>livingNum(x,2)).join(' / '):'Não informado');richSetText('perf-temperature',cpuFresh&&Number.isFinite(diagnostics.thermal?.celsius)?livingNum(diagnostics.thermal.celsius,1)+' °C · componente não identificado':'Não informado');
 }
 async function refresh(){if(busy||document.hidden||page!=='performance'||livingIdleActive)return;busy=true;$('#perf-refresh').disabled=true;try{await Promise.allSettled([refreshTV(),(async()=>{try{const data=await localJSON('/api/performance');if(!data||!Number.isFinite(data.at))throw Error('Leitura incompleta');diagnostics=data;diagError=''}catch(error){diagError=error.message}})()]);horizonReadBluetooth();paint()}finally{busy=false;$('#perf-refresh').disabled=false}if(diagnostics?.cpu?.warmingUp&&!diagError&&warmRetries++<2)setTimeout(refresh,3200)}
 $('#perf-refresh').onclick=refresh;$('#perf-bt-open').onclick=()=>horizonBluetoothPanel();
 $('#perf-process-refresh').onclick=async()=>{const button=$('#perf-process-refresh'),target=$('#perf-process-list');button.disabled=true;target.textContent='Consultando a TV…';try{const data=await localJSON('/api/memory',22000);target.replaceChildren();for(const row of (data.processes||[]).slice(0,8)){const el=document.createElement('div');el.className='perf-process-row';const name=document.createElement('span'),size=document.createElement('b');name.textContent=row.name;size.textContent=livingNum(row.pssKiB/1024,1)+' MiB';el.append(name,size);target.append(el)}if(!target.children.length)target.textContent='O Android não retornou a lista de processos.'}catch(error){target.textContent=error.message}finally{button.disabled=false}};
 const baseNavigate=navigate;navigate=function(next){baseNavigate(next);document.body.classList.toggle('performance-view',next==='performance');section.hidden=next!=='performance';if(next==='performance'){paint();refresh()}};document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));
 const baseSystem=paintSystem;paintSystem=function(){baseSystem();if(page==='performance')window.PeepPerformance.paint()};
 const baseBT=horizonReadBluetooth;horizonReadBluetooth=function(){baseBT();if(page==='performance')paint()};
 PeepRuntime.job('diagnostics',15000,refresh,()=>page==='performance'&&!livingIdleActive);window.PeepPerformance={refresh,paint,history,get diagnostics(){return diagnostics}};
})();
